s,rc=call("POST","/ar-receipts","finance",{"customer_id":s0["customer_id"],"amount":dp,"method":"transfer","entity_id":E,"notes":TAG,"allocations":[{"order_id":oid,"amount":dp}]},ent=E,show=100)
print("  saldo sebelum",bal(),"reservation_expires_at",s0.get("reservation_expires_at"))
