r=d.ar_receipts.find_one({"id":rc["id"]},{"_id":0}); print("  kuitansi DP",{k:r.get(k) for k in("number","status","amount","unallocated","deposit_amount")},r.get("allocations"))
print("  jurnal",[(j.get("number"),j.get("source_type"),j.get("description","")[:50],[(l.get("account_code"),l.get("debit"),l.get("credit")) for l in j.get("lines",[])]) for j in d.journal_entries.find({"entity_id":E}).sort("created_at",-1).limit(2)])
call("GET","/ar-receipts/deposit","finance",q={"customer_id":"cust_toko_kain"},ent=E,show=300)
s,j=call("GET","/ar-receipts/open-orders","finance",q={"customer_id":"cust_toko_kain"},ent=E,show=10)
print("  layar kasir AR masih menagih SO kedaluwarsa?",[(o.get("number") or o.get("order_number"),o.get("status"),o.get("outstanding") or o.get("remaining")) for o in (j if isinstance(j,list) else j.get("items",[])) if (o.get("order_id")==oid or o.get("id")==oid)])
print("-- buka lagi pesanan kedaluwarsa")
for path,body in ((f"/sales-orders/{oid}/confirm",{}),(f"/sales-orders/{oid}/verify",{"note":TAG}),(f"/sales-orders/{oid}/submit-for-approval",{}),(f"/sales-orders/{oid}/release",{}),(f"/sales-orders/{oid}/cancel",{"reason":TAG+" batal sesudah kedaluwarsa"})):
    call("POST",path,"salesadmin",body,ent=E,show=170)
print("  void kuitansi DP untuk mengembalikan dana?")
call("POST",f"/ar-receipts/{rc['id']}/void","finance",{"reason":TAG+" SO kedaluwarsa"},ent=E,show=200)
print("  saldo akhir",bal()); so_line(oid)
